"""Turn off core's substitute "Generated by Odoo" PDF for UBL purchase imports,
on a core that supports the switch.

Sets `account_edi_ubl_cii.disable_pdf_in_xml` so core does not render a
substitute PDF that would take the main-attachment slot from the vendor's real
document. The setting is global and also affects genuine XML-only Peppol
invoices, so `account.move._ai_apply_substitute_pdf_policy` decides whether to
write it and writes nothing on a core that does not read the key. It runs once,
so an administrator who later resets the switch keeps their choice.
"""

import logging

from odoo import SUPERUSER_ID, api

_logger = logging.getLogger(__name__)


def migrate(cr, version):
    if not version:
        return

    env = api.Environment(cr, SUPERUSER_ID, {})
    written = env["account.move"]._ai_apply_substitute_pdf_policy()
    _logger.info(
        "goodahead_invoice_ai_import 19.0.3.1.0: substitute-PDF switch -> %s",
        "True" if written else "not written (this core does not read it)",
    )
